const EMAIL_RE = /^[^@\s]+@[^@\s]+\.[A-Za-z]{2,}$/;
const REQUIRED = ['record_id', 'kind', 'display_name', 'email'];
const STOP = { timeout: 'timeout_not_approve', reject: 'rejected', rejected: 'rejected', missing: 'decision_missing', '': 'decision_missing' };
const REASON_JA = {
  duplicate_registration: '同じ登録キーまたは同じ顧客が台帳に既にあります。二重登録になるため書き込みを止めました。',
  idempotency_conflict: '同じ登録キーなのに中身が違います。衝突として止めました。',
  id_collision: '同じ顧客IDなのに中身が違います。衝突として止めました。',
  invalid_payload: '必須項目の欠落または形式不正です。台帳には書いていません。',
  timeout_not_approve: '待ち時間が切れました。タイムアウトは承認ではありません。台帳には書いていません。',
  rejected: '人が却下しました。台帳には書いていません。',
  decision_missing: '判定が空です。空の判定は承認ではありません。',
  unknown_decision: '判定が approve / reject / timeout 以外です。承認として扱いません。',
  unknown_hold_target: '保留中の書き込みが見つかりません。勝手には書きません。',
  unknown_event_type: '未知のイベント種別です。書き込みしていません。'
};

function payloadHash(record) {
  const identity = {
    display_name: String(record.display_name || ''),
    email: String(record.email || ''),
    kind: String(record.kind || ''),
    record_id: String(record.record_id || '')
  };
  const blob = JSON.stringify(identity);
  return 'sha256-n8n-illustration:' + blob.length + ':' + identity.record_id;
}

function validate(record, key) {
  const errors = [];
  if (!record || typeof record !== 'object') return ['record-not-object'];
  if (!String(key || '').trim()) errors.push('idempotency_key-empty');
  for (const field of REQUIRED) {
    const value = record[field];
    if (typeof value !== 'string' || !value.trim()) errors.push('missing-' + field);
  }
  if (record.kind && record.kind !== 'customer') errors.push('kind-not-allowed');
  if (record.email && !EMAIL_RE.test(String(record.email))) errors.push('email-malformed');
  return errors;
}

function needsHuman(event, reason, extra) {
  return Object.assign({
    event_id: event.event_id,
    status: 'needs_human',
    reason,
    written: false,
    message_ja: REASON_JA[reason],
    timeout_is_approve: false
  }, extra || {});
}

class Guard {
  constructor(ledger) {
    this.ledger = JSON.parse(JSON.stringify(ledger || { records: [] }));
    this.ledger.records = this.ledger.records || [];
    this.ledger.synthetic = true;
    this.byKey = {};
    this.byId = {};
    for (const row of this.ledger.records) {
      row.payload_hash = row.payload_hash || payloadHash(row);
      if (row.idempotency_key) this.byKey[row.idempotency_key] = row;
      if (row.record_id) this.byId[row.record_id] = row;
    }
    this.holds = {};
    this.needs_human = [];
    this.trace = [];
  }
  processEvents(events) {
    for (const event of events) this.processEvent(event);
    return this.result();
  }
  processEvent(event) {
    let outcome;
    if (event.event_type === 'write_attempt') outcome = this.writeAttempt(event, false);
    else if (event.event_type === 'human_decision') outcome = this.humanDecision(event);
    else {
      outcome = needsHuman(event, 'unknown_event_type');
      this.needs_human.push(outcome);
    }
    this.trace.push({
      event_id: event.event_id,
      event_type: event.event_type,
      status: outcome.status,
      reason: outcome.reason || null,
      written: !!outcome.written
    });
    return outcome;
  }
  stop(event, reason, extra) {
    const item = needsHuman(event, reason, extra);
    this.needs_human.push(item);
    return item;
  }
  writeAttempt(event, fromHold) {
    const record = event.record || {};
    const key = String(event.idempotency_key || '').trim();
    const errors = validate(record, key);
    if (errors.length) return this.stop(event, 'invalid_payload', { validation_errors: errors, record_id: record.record_id });
    const digest = payloadHash(record);
    const existingKey = this.byKey[key];
    if (existingKey) {
      return this.stop(event, existingKey.payload_hash !== digest ? 'idempotency_conflict' : 'duplicate_registration', { record_id: record.record_id, idempotency_key: key });
    }
    const existingId = this.byId[record.record_id];
    if (existingId) {
      return this.stop(event, existingId.payload_hash !== digest ? 'id_collision' : 'duplicate_registration', { record_id: record.record_id });
    }
    if (event.hold_for_human && !fromHold) {
      this.holds[event.event_id] = { event, record, idempotency_key: key, payload_hash: digest };
      return { status: 'held', written: false, event_id: event.event_id, record_id: record.record_id };
    }
    const row = {
      record_id: record.record_id,
      kind: record.kind,
      display_name: record.display_name,
      email: record.email,
      source: record.source,
      idempotency_key: key,
      payload_hash: digest,
      written_at: event.occurred_at,
      source_event_id: event.event_id
    };
    if (event.approved_from_event_id) row.approved_from_event_id = event.approved_from_event_id;
    this.ledger.records.push(row);
    this.byKey[key] = row;
    this.byId[row.record_id] = row;
    return { status: 'written', written: true, event_id: event.event_id, record_id: row.record_id };
  }
  humanDecision(event) {
    const target = event.target_event_id;
    const decision = event.decision == null ? '' : String(event.decision).trim().toLowerCase();
    const held = target ? this.holds[target] : null;
    if (target) delete this.holds[target];
    if (!held) return this.stop(event, 'unknown_hold_target', { target_event_id: target, decision: decision || null });
    if (decision === 'approve') {
      const writeEvent = Object.assign({}, held.event, {
        event_id: event.event_id,
        occurred_at: event.occurred_at,
        hold_for_human: false,
        approved_from_event_id: held.event.event_id
      });
      const outcome = this.writeAttempt(writeEvent, true);
      outcome.target_event_id = target;
      outcome.decision = decision;
      return outcome;
    }
    if (Object.prototype.hasOwnProperty.call(STOP, decision)) {
      return this.stop(event, STOP[decision], { target_event_id: target, decision, held_event_id: held.event.event_id, record_id: held.record.record_id });
    }
    return this.stop(event, 'unknown_decision', { target_event_id: target, decision, held_event_id: held.event.event_id });
  }
  result() {
    return {
      meta: { ticket: 'EARN-SHOWCASE-P3-20260916', synthetic: true, timeout_is_approve: false },
      ledger: this.ledger,
      holds_open: Object.keys(this.holds).map((id) => ({ event_id: id, status: 'held', written: false })),
      needs_human: this.needs_human,
      trace: this.trace
    };
  }
}

const body = $input.first().json || {};
const ledger = body.ledger || { records: [] };
const events = Array.isArray(body.events) ? body.events : [body.event || body];
const result = new Guard(ledger).processEvents(events);
result.live_send = 'false';
result.illustration_only = true;
result.note_ja = 'n8n は分岐の見本。検品の正本は runner/failstop.py。';
return [{ json: result }];
